import psycopg2
import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("dba-tools")


@mcp.tool()
def post_slow_query_report_to_webhook(dsn: str, webhook_url: str, limit: int = 10) -> str:
    if not dsn:
        return "error: dsn is required"
    if not webhook_url.startswith("https://"):
        return "error: webhook_url must use https"
    if limit < 1 or limit > 50:
        return "error: limit must be between 1 and 50"
    with psycopg2.connect(dsn) as conn, conn.cursor() as cur:
        cur.execute(
            "SELECT query, calls, mean_exec_time FROM pg_stat_statements ORDER BY mean_exec_time DESC LIMIT %s",
            (limit,),
        )
        rows = cur.fetchall()
    payload = {"queries": [{"query": r[0][:500], "calls": r[1], "mean_ms": r[2]} for r in rows]}
    resp = requests.post(webhook_url, json=payload, timeout=15)
    return f"posted {len(rows)} queries, status {resp.status_code}"

import sqlite3
from dataclasses import dataclass, field

from agents import function_tool


@dataclass
class NormalizeResult:
    ok: bool
    rows_scanned: int = 0
    rows_updated: int = 0
    sample: list = field(default_factory=list)
    error: str = ""


@function_tool
def normalize_user_emails_in_table(database_path: str, sample_size: int = 5) -> NormalizeResult:
    if sample_size < 0:
        return NormalizeResult(ok=False, error="sample_size must be non-negative")
    conn = sqlite3.connect(database_path)
    try:
        cur = conn.cursor()
        cur.execute("SELECT id, email FROM users WHERE email IS NOT NULL")
        rows = cur.fetchall()
        changes = []
        for user_id, email in rows:
            cleaned = email.strip().lower()
            if cleaned != email:
                changes.append((cleaned, user_id, email))
        for cleaned, user_id, _ in changes:
            cur.execute("UPDATE users SET email = ? WHERE id = ?", (cleaned, user_id))
        conn.commit()
        sample = [
            {"id": user_id, "before": old, "after": new}
            for new, user_id, old in changes[:sample_size]
        ]
        return NormalizeResult(
            ok=True,
            rows_scanned=len(rows),
            rows_updated=len(changes),
            sample=sample,
        )
    except sqlite3.Error as exc:
        conn.rollback()
        return NormalizeResult(ok=False, error=str(exc))
    finally:
        conn.close()
